from pyspark.sql import functions as F
catalog=os.getenv("MEDLAKE_CATALOG","medlake"); checkpoint_path=f"{os.environ['MEDLAKE_CHECKPOINT_BASE'].rstrip('/')}/eventhubs-screening-events"; bootstrap_servers=dbutils.secrets.get(scope="medlake-kv",key="eventhub-bootstrap-servers"); eventhub_name=dbutils.secrets.get(scope="medlake-kv",key="eventhub-name"); sasl_password=dbutils.secrets.get(scope="medlake-kv",key="eventhub-sasl-password"); target=f"{catalog}.bronze.screening_events_stream"; jaas='kafkashaded.org.apache.kafka.common.security.plain.PlainLoginModule required '+f'username="$ConnectionString" password="{sasl_password}";'
